import { useState } from 'react';import { Alert,Pressable,StyleSheet,Text,View } from '@/platform/react-native';import { useLocalSearchParams,router } from '@/router';import { useMutation,useQuery,useQueryClient } from '@tanstack/react-query';import { Ionicons } from '@/platform/icons';import { api } from '@/lib/api';import { Badge,Button,Card,Header,Input,Muted,Screen,useAppTheme } from '@/components/UI';
export default function Verification(){const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const qc=useQueryClient();const[name,setName]=useState('');const[reg,setReg]=useState('');const[evidence,setEvidence]=useState('');const[notes,setNotes]=useState('');const{data}=useQuery<any>({queryKey:['verification',id],queryFn:async()=>(await api.get(`/communities/${id}/verification`)).data});const submit=useMutation({mutationFn:async()=>api.post(`/communities/${id}/verification`,{organisationName:name,registrationNumber:reg||undefined,evidenceUrl:evidence,notes}),onSuccess:()=>{qc.invalidateQueries({queryKey:['verification',id]});Alert.alert('Verification submitted','CDA Connect will display the verified badge only after evidence is reviewed.')}});return <Screen scroll><Header title="Community Verification" right={<Pressable onPress={()=>(router.canGoBack()?router.back():router.replace('/'))}><Ionicons name="close" size={26} color={palette.text}/></Pressable>}/><Card><View style={s.row}><Ionicons name="shield-checkmark" size={32} color={data?.IsVerified?palette.success:palette.primary}/><View style={{flex:1}}><Text style={[s.title,{color:palette.text}]}>{data?.IsVerified?'✓ Verified Community':'Verification status'}</Text><Muted>{data?.IsVerified?'This community has completed platform verification.':data?.Status?`Latest request: ${data.Status}`:'Submit organisational evidence for review.'}</Muted></View>{data?.Status?<Badge text={data.Status} tone={data.Status==='APPROVED'?'green':'orange'}/>:null}</View></Card><Muted>Verification helps members distinguish official groups from impersonators. Evidence is not displayed publicly.</Muted><Input placeholder="Official organisation name" value={name} onChangeText={setName}/><Input placeholder="Registration number (optional)" value={reg} onChangeText={setReg}/><Input placeholder="Secure evidence file URL" value={evidence} onChangeText={setEvidence} autoCapitalize="none"/><Input placeholder="Notes for verification reviewer" multiline value={notes} onChangeText={setNotes}/><Button title="Submit for Verification" onPress={()=>submit.mutate()} loading={submit.isPending} disabled={name.length<2||!evidence.startsWith('http')}/></Screen>}
const s=StyleSheet.create({row:{flexDirection:'row',alignItems:'center',gap:12},title:{fontSize:17,fontWeight:'900'}})
